using namespace pulsetrace;
namespace {int checks{};void check(bool b,const char *m){++checks;if(!b)throw std::runtime_error(m);}template<class F>void rejects(F f,const char *m){bool threw=false;try{f();}catch(...){threw=true;}check(threw,m);}void wait(UpdateService &u){const auto deadline=GetTickCount64()+5000;while(u.status().value("busy",false)){if(GetTickCount64()>deadline)throw std::runtime_error("async update test timeout");Sleep(5);}}
Json attachment(const std::string &name,const std::string &source,std::size_t size){return {{"name",name},{"size",size},{"browser_download_url",source=="github"?"https://github.com/zhangchengxuv/PulseTrace/releases/download/v9.0.0/"+name:"https://gitee.com/zhangchenxuv/pulse-trace/releases/download/v9.0.0/"+name}};}
}
int main(){try{
 const std::vector<std::string> sequence={"1.0.0-alpha","1.0.0-alpha.1","1.0.0-alpha.beta","1.0.0-beta","1.0.0-beta.2","1.0.0-beta.11","1.0.0-rc.1","1.0.0"};for(std::size_t i=1;i<sequence.size();i++)check(SemVersion::parse(sequence[i-1]).compare(SemVersion::parse(sequence[i]))<0,"official SemVer precedence");
 check(SemVersion::parse("1.0.0+abc").compare(SemVersion::parse("1.0.0+def"))==0,"build metadata excluded");check(SemVersion::parse("0.10.0").compare(SemVersion::parse("0.9.99"))>0,"numeric version comparison");check(SemVersion::parse("999999999999999999999.0.0").compare(SemVersion::parse("10.0.0"))>0,"numeric version no overflow");for(auto s:{"v1.2.3","1.2","01.0.0","1.0.0-01","1.0.0-","1.0.0+","1.0.0+a+b","1.0.-1"})rejects([&]{SemVersion::parse(s);},"invalid SemVer rejected");
 for(auto u:{"http://github.com/x","https://evil.example/x","https://github.com@evil.example/x","https://github.com/other/PulseTrace/releases/x","https://gitee.com/other/repo/releases/x","https://github.com:443/zhangchengxuv/PulseTrace/releases/x"})check(!trusted_update_url(u),"untrusted URL rejected");check(trusted_update_url("https://release-assets.githubusercontent.com/test",true)&&!trusted_update_url("https://release-assets.githubusercontent.com/test"),"CDN only reachable through trusted redirect");
 const auto root=std::filesystem::absolute("data/tests/updates-"+std::to_string(GetCurrentProcessId())+"-"+std::to_string(GetTickCount64()));std::filesystem::create_directories(root);
 std::string binary(2048,'\0');auto *dos=reinterpret_cast<IMAGE_DOS_HEADER*>(binary.data());dos->e_magic=IMAGE_DOS_SIGNATURE;dos->e_lfanew=128;auto *nt=reinterpret_cast<IMAGE_NT_HEADERS64*>(binary.data()+128);nt->Signature=IMAGE_NT_SIGNATURE;nt->FileHeader.Machine=IMAGE_FILE_MACHINE_AMD64;nt->OptionalHeader.Magic=IMAGE_NT_OPTIONAL_HDR64_MAGIC;{std::ofstream out(root/"mock.exe",std::ios::binary);out.write(binary.data(),binary.size());}
 const auto digest=sha256_file(root/"mock.exe");const std::string name="PulseTrace-Setup-v9.0.0-x64.exe";check(!trusted_installer(root/"mock.exe","")&&!trusted_installer(root/"mock.exe",std::string(64,'0')),"unsigned/unpinned EXE never trusted");
 const auto checksum=digest+"  "+name+"\n";check(parse_checksum(checksum,name)==digest,"checksum filename/hash validated");rejects([&]{parse_checksum(digest+"  wrong.exe",name);},"wrong checksum filename rejected");
 Json gh=Json::array({{{"tag_name","v9.0.0"},{"body","real release notes"},{"assets",Json::array({attachment(name,"github",binary.size()),attachment(name+".sha256","github",100)})}}});
 Json gt=Json::array({{{"id",81},{"tag_name","v9.0.0"},{"assets",Json::array({"unrelated-string-not-github-schema"})}}});Json ga=Json::array({attachment(name,"gitee",binary.size()),attachment(name+".sha256","gitee",100)});
 check(github_release(gh,"stable")->version=="9.0.0","GitHub native schema parsed");bool attached=false;check(gitee_release(gt,"stable",[&](auto id){attached=id==81;return ga;})->source=="gitee"&&attached,"Gitee uses separate attachment endpoint");
 auto preview=gh;preview[0]["tag_name"]="v10.0.0-rc1";preview[0]["prerelease"]=false;check(!github_release(preview,"stable"),"stable excludes mislabeled prerelease");
 UpdateAsset a=*github_release(gh,"stable");a.sha256=digest;auto b=a;b.source="gitee";check(choose_updates({a,b},"8.0.0").size()==2,"same artifact dual-source fallback");check(choose_updates({a},"9.0.0").empty()&&choose_updates({a},"10.0.0").empty(),"no reinstall/downgrade");b.sha256=std::string(64,'0');rejects([&]{choose_updates({a,b},"8.0.0");},"source disagreement blocked");
 a.latency_ms=50;b=a;b.source="gitee";b.latency_ms=1;check(choose_updates({a,b},"8.0.0")[0].source=="gitee","same validated version prefers responsive source");b.version="8.5.0";check(choose_updates({a,b},"8.0.0")[0].version=="9.0.0","faster old mirror cannot displace newer release");
 int scenario=0;auto transport=[&](const std::string &url,std::uint64_t,const std::atomic<bool> &cancel,const auto &sink){std::string body;if(scenario==1)throw std::runtime_error("Network timeout");if(scenario==2)throw std::runtime_error("Release server HTTP 403");if(scenario==3){while(!cancel)Sleep(5);throw std::runtime_error("cancelled");}if(scenario==6&&url.find("github.com")!=url.npos)throw std::runtime_error("GitHub unavailable");if(scenario==7&&url.find("gitee.com")!=url.npos)throw std::runtime_error("Gitee unavailable");if(url.find(".sha256")!=url.npos)body=checksum;else if(url.ends_with(".exe")){if(scenario==4)throw std::runtime_error("Download interrupted");body=binary;if(scenario==5)body[1000]='x';if(scenario==8&&url.find("github.com")!=url.npos)throw std::runtime_error("Selected source interrupted");}else if(url.find("attach_files")!=url.npos)body=ga.dump();else body=url.find("gitee.com")!=url.npos?gt.dump():gh.dump();sink(body.data(),body.size());};
 UpdateService updater(root/"service",transport);updater.check("stable","auto");wait(updater);check(updater.status()["phase"]=="available"&&updater.status()["providers"].size()==2,"asynchronous dual-source check");updater.download();wait(updater);check(updater.status()["phase"]=="manual_install"&&updater.status()["downloaded"]==true&&updater.status()["can_install"]==false,"verified hash unsigned download stays manual");rejects([&]{updater.verified_installer();},"untrusted automatic execution blocked");
 scenario=4;updater.download();wait(updater);check(updater.status()["phase"]=="error","both downloads interrupted reported");check(!std::filesystem::exists(root/"service"/"updates"/(name+".part")),"partial download cleaned");scenario=5;updater.download();wait(updater);check(updater.status()["phase"]=="error","corrupt download rejected");
 for(int mode:{1,2}){scenario=mode;updater.check("stable","auto");wait(updater);check(updater.status()["phase"]=="error"&&updater.status()["providers"].size()==2,"network/API errors retained for both sources");}
 for(int mode:{6,7}){scenario=mode;updater.check("stable","auto");wait(updater);check(updater.status()["phase"]=="available"&&updater.status()["partial_sources"]==true,"one available source still discovers update");}
 scenario=0;updater.check("stable","auto");wait(updater);scenario=8;updater.download();wait(updater);check(updater.status()["phase"]=="manual_install","download fallback uses matching version/hash only");
 scenario=3;updater.check("stable","github");rejects([&]{updater.check("stable","gitee");},"concurrent operation refused");updater.cancel();wait(updater);check(updater.status()["phase"]=="cancelled","user cancellation preserved");
 std::cout<<checks<<" updater checks passed\n";return 0;
 }catch(const std::exception &e){std::cerr<<e.what()<<'\n';return 1;}}
